function export:RegenerateBuddies()
	self = self._graph;
	-- Regenerate buddies excluding primary (library mission subversion) buddy if a library mission is active
	System:Log("BSQManager: Regenerating buddies for Mike's place");
	self.MikesPlace_PawnsReady = false;
	if (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self._type.en_62_PrimaryCheck(self);
