function export:en_62_PrimaryCheck()
	self[62].Marty = self.Entity_MartyAlencar;
	self[62].Nasreen = self.Entity_NasreenDavar;
	self[62].Andre = self.Entity_AndreHyppolite;
	self[62].Frank = self.Entity_FrankBilders;
	self[62].Xianyong = self.Entity_XianyongBai;
	self[62].Hakim = self.Entity_HakimEchebbi;

	-- Prevent despawning library mission (subversion) buddy
	if (GetBuddiesManager():GetPrimaryBuddyName() == "Marty_Alencar") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[62].Marty = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Nasreen_Davar") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[62].Nasreen = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Andre_Hyppolite") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[62].Andre = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Frank_Bilders") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[62].Frank = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Xianyong_Bai") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[62].Xianyong = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Hakim_Echebbi") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[62].Hakim = nil;
	end
end;

